package com.vignesh.banking.service;
import com.vignesh.banking.dto.*;import com.vignesh.banking.model.*;import com.vignesh.banking.repository.*;import com.vignesh.banking.security.JwtService;import org.springframework.security.authentication.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import java.math.BigDecimal;import java.util.UUID;
@Service public class AuthService{ private final UserRepository users; private final AccountRepository accounts; private final PasswordEncoder enc; private final AuthenticationManager auth; private final JwtService jwt; public AuthService(UserRepository u,AccountRepository a,PasswordEncoder e,AuthenticationManager am,JwtService j){users=u;accounts=a;enc=e;auth=am;jwt=j;} public AuthResponse register(AuthRequest r){ if(users.findByEmail(r.email()).isPresent()) throw new RuntimeException("Email already registered"); Role role=r.role()==null?Role.CUSTOMER:Role.valueOf(r.role().toUpperCase()); User u=new User(); u.setEmail(r.email()); u.setPassword(enc.encode(r.password())); u.setFullName(r.fullName()); u.setRole(role); users.save(u); Account acc=new Account(); acc.setAccountNumber("ACC"+UUID.randomUUID().toString().substring(0,8).toUpperCase()); acc.setBalance(BigDecimal.valueOf(1000)); acc.setOwner(u); accounts.save(acc); return new AuthResponse(jwt.generate(u.getEmail(),u.getRole().name()),u.getEmail(),u.getRole().name()); } public AuthResponse login(AuthRequest r){ auth.authenticate(new UsernamePasswordAuthenticationToken(r.email(),r.password())); var u=users.findByEmail(r.email()).orElseThrow(); return new AuthResponse(jwt.generate(u.getEmail(),u.getRole().name()),u.getEmail(),u.getRole().name()); } }
